package com.stocksentinel;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import com.stocksentinel.custom.*;import com.stocksentinel.notification.*;import com.stocksentinel.market.*;
import java.sql.*;import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.*;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"custom-strategies.enabled=true","custom-strategies.notifications-enabled=true","custom-strategies.worker-enabled=false","wecom.enabled=true","wecom.bot-id=test-bot","wecom.bot-secret=test-only-credential","wecom.chat-id=test-group","wecom.chat-ids=second-group","wecom.worker-enabled=false","llm.enabled=false"})
@AutoConfigureMockMvc @Import(CustomStrategiesLocalDatabaseIT.TimeConfig.class) @EnabledIfEnvironmentVariable(named="STOCKSENTINEL_TEST_DB_URL",matches="jdbc:postgresql:.*")
class CustomStrategiesLocalDatabaseIT {
    static final LocalDate DAY=LocalDate.of(2026,10,22),TODAY=DAY.plusDays(1);
    static final String SCHEMA="stocksentinel_custom_"+UUID.randomUUID().toString().replace("-","");
    @TestConfiguration(proxyBeanMethods=false)static class TimeConfig{@Bean @Primary Clock customClock(){return Clock.fixed(TODAY.atTime(16,0).toInstant(ZoneOffset.ofHours(8)),ZoneId.of("Asia/Shanghai"));}}
    static Connection connection()throws Exception{return DriverManager.getConnection(System.getenv("STOCKSENTINEL_TEST_DB_URL"),System.getenv("STOCKSENTINEL_TEST_DB_USER"),System.getenv("STOCKSENTINEL_TEST_DB_PASSWORD"));}
    @DynamicPropertySource static void database(DynamicPropertyRegistry r)throws Exception{if(!SCHEMA.matches("stocksentinel_custom_[a-f0-9]{32}"))throw new IllegalStateException();try(var c=connection();var s=c.createStatement()){s.execute("CREATE SCHEMA \""+SCHEMA+"\"");}r.add("spring.datasource.url",()->System.getenv("STOCKSENTINEL_TEST_DB_URL")+"?currentSchema="+SCHEMA);r.add("spring.datasource.username",()->System.getenv("STOCKSENTINEL_TEST_DB_USER"));r.add("spring.datasource.password",()->System.getenv("STOCKSENTINEL_TEST_DB_PASSWORD"));r.add("spring.flyway.default-schema",()->SCHEMA);}
    @AfterAll static void clean()throws Exception{if(!SCHEMA.matches("stocksentinel_custom_[a-f0-9]{32}"))throw new IllegalStateException();try(var c=connection();var s=c.createStatement()){s.execute("DROP SCHEMA \""+SCHEMA+"\" CASCADE");}}
    @Autowired CustomStrategyService service;@Autowired CustomStrategyMapper mapper;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired MockMvc http;
    @MockitoBean SmartBotClient bot;@MockitoBean MarketCollectionService market;
    JsonNode view(Object value){return json.valueToTree(value);}
    UUID create(){return UUID.fromString(view(service.save(null,new CustomStrategyService.Save(0,"自定义观察","模拟样例",CustomRuleEngineTest.definition()))).path("id").asText());}
    CustomStrategyService.Execute request(int revision,LocalDate day,boolean notify,String id){return new CustomStrategyService.Execute(revision,day,null,notify,id);}
    void validate(UUID id){service.execute(id,request(1,DAY,false,null),true);}
    void todayData(){db.update("INSERT INTO market_daily_bar(symbol,trade_date,open_price,high_price,low_price,close_price,volume,amount,adjustment,source,fetched_at) SELECT symbol,?,open_price,high_price,low_price,close_price,volume,amount,adjustment,source,fetched_at FROM market_daily_bar WHERE trade_date=?",TODAY,DAY);db.update("INSERT INTO market_indicator_daily(symbol,trade_date,ma5,ma10,ma20,ma60,dif,dea,macd_hist,volume_ratio,calculation_version,adjustment,calculated_at) SELECT symbol,?,ma5,ma10,ma20,ma60,dif,dea,macd_hist,volume_ratio,calculation_version,adjustment,calculated_at FROM market_indicator_daily WHERE trade_date=?",TODAY,DAY);db.update("INSERT INTO market_close_confirmation(trade_date,source) VALUES(?,'TEST')",TODAY);}
    @BeforeEach void seed(){db.execute("TRUNCATE custom_daily_strategy,stock_info,market_calendar CASCADE");for(var day:List.of(DAY.minusDays(1),DAY,TODAY))db.update("INSERT INTO market_calendar(trade_date,exchange,is_open,source) VALUES(?,'CN',true,'TEST')",day);db.update("INSERT INTO stock_info(symbol,name,exchange) VALUES('000731','四川美丰','SZ'),('600487','亨通光电','SH')");db.update("INSERT INTO stock_watchlist(symbol) VALUES('000731')");for(String symbol:List.of("000731","600487"))for(var day:List.of(DAY.minusDays(1),DAY)){db.update("INSERT INTO market_daily_bar(symbol,trade_date,open_price,high_price,low_price,close_price,volume,amount,adjustment,source,fetched_at) VALUES(?,?,9,11,8,10,100000,200000000,'QFQ','TEST',now()-interval '20 minutes')",symbol,day);db.update("INSERT INTO market_indicator_daily(symbol,trade_date,ma5,ma10,ma20,ma60,dif,dea,macd_hist,volume_ratio,calculation_version,adjustment,calculated_at) VALUES(?,?,9,9,9,8,0.5,0.3,0.4,1.8,'ma-macd-vol-v1','QFQ',now()-interval '10 minutes')",symbol,day);}reset(bot,market);}
    @Test void savesImmutableRevisionsAndDetectsConcurrentEditing(){UUID id=create();assertEquals(1,view(service.detail(id)).path("currentRevision").asInt());service.save(id,new CustomStrategyService.Save(1,"观察v2","",CustomRuleEngineTest.definition()));assertEquals("自定义观察",mapper.revision(id,1).name);assertEquals("观察v2",mapper.revision(id,2).name);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.save(id,new CustomStrategyService.Save(1,"过期编辑","",CustomRuleEngineTest.definition())));}
    @Test void previewRecordsEvidenceWithoutSignalsNoticesOrExternalCalls(){UUID id=create();var result=view(service.execute(id,request(1,DAY,false,null),true));assertEquals(1,result.path("matched").asInt());assertEquals(0,result.path("skipped").asInt());assertTrue(view(service.detail(id)).path("validated").asBoolean());assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_event",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_notice",Integer.class));verifyNoInteractions(bot,market);}
    @Test void activationRequiresSuccessfulPreviewAndNewDraftPreservesOldActive(){UUID id=create();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.state(id,new CustomStrategyService.State(1,true)));validate(id);service.state(id,new CustomStrategyService.State(1,true));service.save(id,new CustomStrategyService.Save(1,"新草稿","",CustomRuleEngineTest.definition()));var detail=view(service.detail(id));assertEquals(2,detail.path("currentRevision").asInt());assertEquals(1,detail.path("activeRevision").asInt());assertFalse(detail.path("validated").asBoolean());service.state(id,new CustomStrategyService.State(2,false));assertEquals(0,view(service.detail(id)).path("activeRevision").asInt());}
    @Test void missingIndicatorsSkipInsteadOfFalseNoMatchOrValidating(){db.update("UPDATE market_indicator_daily SET calculated_at=now()-interval '30 minutes'");UUID id=create();var result=view(service.execute(id,request(1,DAY,false,null),true));assertEquals(1,result.path("skipped").asInt());assertEquals("REQUIRED_FACTOR_UNAVAILABLE",result.at("/results/0/code").asText());assertFalse(view(service.detail(id)).path("validated").asBoolean());}
    @Test void priceOnlyRuleDoesNotRequireUnrelatedIndicators(){db.update("DELETE FROM market_indicator_daily");var definition=CustomRuleEngineTest.definition();var rules=(ArrayNode)definition.at("/rules/children");rules.removeAll();rules.addObject().put("factor","CLOSE").put("operator","GT").putObject("operand").put("value",5);UUID id=UUID.fromString(view(service.save(null,new CustomStrategyService.Save(0,"价格观察","",definition))).path("id").asText());assertEquals(1,view(service.execute(id,request(1,DAY,false,null),true)).path("matched").asInt());}
    @Test void missingChipsRemainExplicitlyUnavailable(){var definition=CustomRuleEngineTest.definition();((ObjectNode)definition.at("/rules/children/1")).put("factor","CHIP90").put("operator","LE").putObject("operand").put("value",.10);UUID id=UUID.fromString(view(service.save(null,new CustomStrategyService.Save(0,"筹码观察","",definition))).path("id").asText());assertEquals(1,view(service.execute(id,request(1,DAY,false,null),true)).path("skipped").asInt());}
    @Test void scanIsIdempotentAndHistoricalNotificationIsRejected(){UUID id=create();validate(id);service.state(id,new CustomStrategyService.State(1,true));var first=view(service.execute(id,request(1,DAY,false,"scan-1"),false));var repeat=view(service.execute(id,request(1,DAY,false,"scan-1"),false));assertEquals(first.path("runId"),repeat.path("runId"));assertEquals(1,db.queryForObject("SELECT count(*) FROM custom_daily_event",Integer.class));service.execute(id,request(1,DAY,false,"scan-2"),false);assertEquals(1,db.queryForObject("SELECT count(*) FROM custom_daily_event",Integer.class));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.execute(id,request(1,DAY,true,"history"),false));}
    @Test void todayNeedsExactSourceConfirmation(){UUID id=create();todayData();db.update("DELETE FROM market_close_confirmation");db.update("INSERT INTO market_close_confirmation(trade_date,source) VALUES(?,'OTHER')",TODAY);var result=view(service.execute(id,request(1,TODAY,false,null),true));assertEquals("SOURCE_CLOSE_CONFIRMATION_REQUIRED",result.at("/results/0/code").asText());assertEquals(0,result.path("matched").asInt());}
    @Test void currentDayNoticesArePerGroupOnceAndPauseStopsFutureClaims(){UUID id=create();validate(id);service.state(id,new CustomStrategyService.State(1,true));todayData();service.execute(id,request(1,TODAY,false,"no-notice"),false);assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_notice",Integer.class));var result=view(service.execute(id,request(1,TODAY,true,"notice"),false));assertEquals(2,result.path("notificationsQueued").asInt());service.execute(id,request(1,TODAY,true,"notice-again"),false);assertEquals(2,db.queryForObject("SELECT count(*) FROM custom_daily_notice",Integer.class));service.state(id,new CustomStrategyService.State(1,false));assertNull(mapper.claim("test-group","token"));mapper.expirePending();assertEquals(2,db.queryForObject("SELECT count(*) FROM custom_daily_notice WHERE status='EXPIRED'",Integer.class));verifyNoInteractions(bot,market);}
    @Test void notificationFailureRollsBackEntireScanButPreservesPriorPreview(){UUID id=create();validate(id);service.state(id,new CustomStrategyService.State(1,true));todayData();db.execute("ALTER TABLE custom_daily_notice ADD CONSTRAINT fixture_custom_reject CHECK(target_chat_id<>'second-group')");try{assertThrows(Exception.class,()->service.execute(id,request(1,TODAY,true,"rollback"),false));assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_event",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_notice",Integer.class));assertEquals(1,db.queryForObject("SELECT count(*) FROM custom_daily_run",Integer.class));}finally{db.execute("ALTER TABLE custom_daily_notice DROP CONSTRAINT fixture_custom_reject");}}
    @Test void httpContractsAndSameOriginProtection()throws Exception{http.perform(get("/manage/index.html")).andExpect(status().isOk()).andExpect(header().string("X-Frame-Options","DENY"));http.perform(get("/api/v1/custom-strategies/catalog")).andExpect(status().isOk()).andExpect(jsonPath("$.factors.length()").value(17));http.perform(post("/api/v1/custom-strategies").header("Origin","https://untrusted.example").contentType("application/json").content("{}")).andExpect(status().isForbidden());http.perform(get("/api/v1/custom-strategies").with(r->{r.setRemoteAddr("10.0.0.1");return r;})).andExpect(status().isForbidden());http.perform(post("/api/v1/custom-strategies").contentType("application/json").content(json.writeValueAsString(Map.of("expectedRevision",0,"name","HTTP策略","description","","definition",CustomRuleEngineTest.definition())))).andExpect(status().isOk()).andExpect(jsonPath("$.currentRevision").value(1));}
    @Test void invalidDefinitionAndUnknownRequestFieldsNeverCreateRows()throws Exception{http.perform(post("/api/v1/custom-strategies").contentType("application/json").content("{\"name\":\"test\",\"sql\":\"drop table stock_info\"}")).andExpect(status().isBadRequest());assertEquals(0,db.queryForObject("SELECT count(*) FROM custom_daily_strategy",Integer.class));}
    @Test void requestIdScopeConflictAndScanScopeCannotBeOverridden(){UUID id=create();validate(id);service.state(id,new CustomStrategyService.State(1,true));service.execute(id,request(1,DAY,false,"same"),false);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.execute(id,request(1,DAY.minusDays(1),false,"same"),false));assertThrows(IllegalArgumentException.class,()->service.execute(id,new CustomStrategyService.Execute(1,DAY,List.of("600487"),false,"other"),false));}
    @Test void unknownSymbolsAndEmptyWatchlistAreNotSilentlyMatched(){UUID id=create();var result=view(service.execute(id,new CustomStrategyService.Execute(1,DAY,List.of("999999"),false,null),true));assertEquals("STOCK_NOT_FOUND",result.at("/results/0/code").asText());assertFalse(view(service.detail(id)).path("validated").asBoolean());}
    @Test void concurrentEditsCannotOverwriteEachOther()throws Exception{UUID id=create();try(var pool=Executors.newFixedThreadPool(2)){Callable<Boolean> edit=()->{try{service.save(id,new CustomStrategyService.Save(1,"并发修改","",CustomRuleEngineTest.definition()));return true;}catch(org.springframework.web.server.ResponseStatusException conflict){assertEquals(409,conflict.getStatusCode().value());return false;}};var a=pool.submit(edit);var b=pool.submit(edit);assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));}assertEquals(2,view(service.detail(id)).path("currentRevision").asInt());assertEquals(2,mapper.revisions(id).size());}
    @Test void wrongAdjustmentAndMixedSourcesNeverProduceSignals(){UUID id=create();db.update("UPDATE market_daily_bar SET source='OTHER' WHERE trade_date=?",DAY.minusDays(1));assertEquals(1,view(service.execute(id,request(1,DAY,false,null),true)).path("skipped").asInt());db.update("UPDATE market_daily_bar SET source='TEST'");var definition=CustomRuleEngineTest.definition().put("adjustment","NONE");service.save(id,new CustomStrategyService.Save(1,"不复权观察","",definition));assertEquals(1,view(service.execute(id,request(2,DAY,false,null),true)).path("skipped").asInt());}
    @Test void oversizedWatchlistIsRejectedRatherThanSilentlyTruncated(){var definition=CustomRuleEngineTest.definition().put("universe","WATCHLIST");definition.putArray("symbols");UUID id=UUID.fromString(view(service.save(null,new CustomStrategyService.Save(0,"关注观察","",definition))).path("id").asText());db.update("INSERT INTO stock_info(symbol,name,exchange) SELECT lpad(n::text,6,'0'),'样例股','SZ' FROM generate_series(1,101)n");db.update("INSERT INTO stock_watchlist(symbol) SELECT symbol FROM stock_info WHERE symbol<>'600487' ON CONFLICT DO NOTHING");var error=assertThrows(org.springframework.web.server.ResponseStatusException.class,()->service.execute(id,request(1,DAY,false,null),true));assertEquals("CUSTOM_SCOPE_EMPTY_OR_OVER_100",error.getReason());}
    @Test void todayChipFactorRequiresItsOwnConfirmation(){todayData();var definition=CustomRuleEngineTest.definition();var children=(ArrayNode)definition.at("/rules/children");children.removeAll();children.addObject().put("factor","CHIP90").put("operator","LE").putObject("operand").put("value",.10);UUID id=UUID.fromString(view(service.save(null,new CustomStrategyService.Save(0,"今日筹码","",definition))).path("id").asText());db.update("INSERT INTO chip_scan_run(trade_date,parameters) VALUES(?,'{}')",TODAY);db.update("INSERT INTO chip_scan_item(trade_date,symbol,status,snapshot) VALUES(?,'000731','MATCHED',CAST(? AS jsonb))",TODAY,"{\"symbol\":\"000731\",\"as_of\":\""+TODAY+"\",\"source\":\"CHIP_EASTMONEY\",\"version\":\"akshare-cyq-210-v1\",\"concentration90\":0.08,\"concentration70\":0.04,\"profit_ratio\":0.5}");assertEquals(1,view(service.execute(id,request(1,TODAY,false,null),true)).path("skipped").asInt());db.update("INSERT INTO market_close_confirmation(trade_date,source) VALUES(?,'CHIP_EASTMONEY')",TODAY);assertEquals(1,view(service.execute(id,request(1,TODAY,false,null),true)).path("matched").asInt());}
    @Test void unknownNoticeNeverReplaysOnAnotherScan(){UUID id=create();validate(id);service.state(id,new CustomStrategyService.State(1,true));todayData();service.execute(id,request(1,TODAY,true,"first"),false);var row=mapper.claim("test-group","owner");mapper.finish(row.id,"owner","UNKNOWN","DELIVERY_UNKNOWN");service.execute(id,request(1,TODAY,true,"again"),false);assertNull(mapper.claim("test-group","next"));assertEquals(2,db.queryForObject("SELECT count(*) FROM custom_daily_notice",Integer.class));}
}
